def check_equation(b2, b3):
    return 5 * b2**2 + 5 * b3**2 + 8 * b2 * b3

target = 63
solutions = []
# Since the equation is symmetric in b2 and b3, we only need to check b2 >= 0 and b3 >= 0
# We can also restrict to |b2|, |b3| <= 8
for b2 in range(-8, 9):
    for b3 in range(-8, 9):
        if check_equation(b2, b3) == target:
            solutions.append((b2, b3))

print("Solutions for 5b2^2 + 5b3^2 + 8b2b3 = 63:", solutions)

